  const m = marketAt(position, ticker); if (!m) return null;
  if (!m.yes) return m.quote ? { bid: m.quote.bid, ask: m.quote.ask, bidSize: null, askSize: null, mid: m.quote.bid && m.quote.ask ? (m.quote.bid + m.quote.ask) / 2 : null, last: m.last ?? null, stale: false, from: 'ticker' } : null;
  const yes = Object.entries(m.yes).map(([p, q]) => [Number(p), q]); const no = Object.entries(m.no).map(([p, q]) => [Number(p), q]);
  const [bid, bidQ] = yes.reduce((b, x) => (x[0] > b[0] ? x : b), [0, 0]);
  const [noBid, askQ] = no.reduce((b, x) => (x[0] > b[0] ? x : b), [0, 0]);
  const ask = noBid ? ONE - noBid : null;
  return { bid, ask, bidSize: bidQ / 100, askSize: askQ / 100, mid: bid && ask !== null ? (bid + ask) / 2 : null, last: m.last ?? null, stale: Boolean(m.stale) };
}

/** Contracts resting ahead of a new bid at `price` (price units) on the `side` ladder. */
export const queueAhead = (position, ticker, side, price) => (marketAt(position, ticker)?.[side]?.[price] ?? 0) / 100;

/**
 * Shadow execution of one resting bid against the Opponent takes that followed it, queue-aware and
 * pessimistic: it joins behind `aheadAtPlace` contracts at its price; only takes that hit its ladder at
 * or through its price advance the queue; pulls ahead are assumed to come from behind it.
 * intent: {ticker, side: 'yes'|'no' ladder, price: price units on that ladder, size: contracts, placedAt: ms}
 * events: arena `take` events (size in hundredths, taker 'yes'|'no', t ms).
 */
export function shadowRest(intent, aheadAtPlace, events) {
  let ahead = Math.round(aheadAtPlace * 100); const want = Math.round(intent.size * 100); let filled = 0; const fills = [];
  for (const e of events) {
    if (e.kind !== 'take' || e.ticker !== intent.ticker || (e.t ?? 0) < intent.placedAt) continue;
    // a YES-ladder bid at p is hit by a taker selling YES (taker 'no') at yes price <= p; a NO-ladder bid at q by a taker buying YES at >= ONE - q
    const hits = intent.side === 'yes' ? e.taker === 'no' && e.price <= intent.price : e.taker === 'yes' && e.price >= ONE - intent.price;
    if (!hits) continue;
    let s = e.size; const eat = Math.min(ahead, s); ahead -= eat; s -= eat;
    const f = Math.min(s, want - filled);
    if (f > 0) { filled += f; fills.push({ t: e.t, size: f / 100 }); }
    if (filled >= want) break;
  }
  return { filled: filled / 100, fills };
}

/** Exact executable book in upstream gaming's graded monetary carrier. */
export function orderBookOf(position, ticker, side = 'yes') {
  const m = marketAt(position, ticker);
  if (!m?.yes || m.stale || ['closed', 'determined', 'settled', 'deactivated'].includes(m.status)) throw new RangeError('known live depth required');
  if (!['yes', 'no'].includes(side)) throw new TypeError('YES or NO book required');
  const levels = (ladder, complement = false) => Object.entries(ladder).map(([p, q]) => ({ price: gradedFromParts(complement ? ONE - Number(p) : Number(p), ONE, 'USD'), quantity: gradedFromParts(q, 100, `kalshi:${ticker}:${side}`) }));
  return { bids: levels(m[side]), asks: levels(m[side === 'yes' ? 'no' : 'yes'], true) };
}

/** Depth, slippage and liquidity shortfall use the one upstream book walk. */
export function walkTake(position, ticker, side, quantityHundredths, action = 'buy') {
  if (!Number.isSafeInteger(quantityHundredths) || quantityHundredths < 1) throw new RangeError('positive quantity in hundredths required');
  if (!['buy', 'sell'].includes(action)) throw new TypeError('buy or sell action required');
  const quantity = gradedFromParts(quantityHundredths, 100, `kalshi:${ticker}:${side}`);
  return (action === 'buy' ? marketBuyWalk : marketSellWalk)(orderBookOf(position, ticker, side), quantity);
}
